import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(n):
        try:
            i = int(next(iterator))
            j = int(next(iterator))
        except StopIteration:
            break

        dist = 0

        while i != j:
            if i > j:
                i //= 2
            else:
                j //= 2
            dist += 1

        results.append(str(dist))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    main()
